// Jobs > Burst > Enable Compilation off: every job runs as plain C#
[BurstCompile]
struct SpawnJob : IJob
{
    public NativeArray<float3> points;
    public void Execute()
    {
        for (int i = 0; i < points.Length; i++)
            points[i] = Place(i);   // a managed breakpoint works here
    }
    static float3 Place(int i) => new float3(i, 0f, 0f);
}

// the Editor compiles Burst in the background: early frames may run managed code;
// for profiling or a Burst-vs-managed comparison, wait for it
[BurstCompile(CompileSynchronously = true)]
struct WarmJob : IJob { public void Execute() { } }

// Edit > Preferences > Jobs > Use Job Threads off:
// every job runs on the main thread right when it is scheduled.
// The same from code (0 workers), and back to automatic:
JobsUtility.JobWorkerCount = 0;
JobsUtility.ResetJobWorkerCount();

// or a single job: the same Execute, the same Burst code, no threads
new SpawnJob { points = points }.Run();

// this job only: no optimizations, with debug info; players respect it too
[BurstCompile(Debug = true)]
struct SpawnJob : IJob { public void Execute() { } }

// all Burst code at once: Jobs > Burst > Native Debug Mode Compilation,
// then attach a native debugger (Visual Studio, Xcode) to the Editor or the player.
// Player: Development Build or Force Debug Information, symbols in lib_burst_generated

// a code breakpoint that Burst supports
System.Diagnostics.Debugger.Break();

[BurstCompile]
struct ScanJob : IJob
{
    public NativeArray<float3> pos;
    public FixedString64Bytes label;   // text in a field: only FixedString

    public void Execute()
    {
        int i = 7;
        float3 p = pos[i];
        Debug.Log("scan started");      // a literal: fine
        Debug.Log($"pos[{i}] = {p}");    // int and float3 arguments: fine
        // Debug.Log("pos " + p);       // concatenation: not supported
        LogManaged(i);                  // does nothing under Burst
    }

    [BurstDiscard]   // left out of Burst compilation; must return void
    static void LogManaged(int i) => Debug.Log(System.DateTime.Now + " " + i);
}

[BurstCompile]
struct HealJob : IJob
{
    public NativeArray<float> hp;
    public float amount;

    public void Execute()
    {
        CheckAmount(amount);   // the call disappears from player builds
        for (int i = 0; i < hp.Length; i++) hp[i] += amount;
    }

    // System.Diagnostics, not UnityEngine: both have a Debug class
    [System.Diagnostics.Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
    static void CheckAmount(float a)
    {
        if (!(a >= 0f))
            throw new System.ArgumentException("amount must be >= 0");
    }
}

