using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using UnityEngine;

[BurstCompile]
struct ApplyDamageJob : IJob
{
    public NativeArray<float> hp;
    public int target;
    public float damage;

    public void Execute()
    {
        CheckIndex(target, hp.Length);   // compiled out of player builds
        hp[target] -= damage;
        Debug.Log($"hp left: {hp[target]}");
    }

    [System.Diagnostics.Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
    static void CheckIndex(int index, int length)
    {
        if (index < 0 || index >= length)
            throw new System.ArgumentOutOfRangeException("index");
    }
}
